class search extends common { const VERSION = '4.3'; const REALNAME = 'Recherche'; const DATADIRECTORY = self::DATA_DIR . 'search/'; const MULTIMODULE = true; const SINGLEINSTANCE = true; public static $actions = [ 'index' => self::ROLE_VISITOR, 'config' => self::ROLE_EDITOR ]; public static $resultList = ''; public static $resultError = ''; public static $resultTitle = ''; public static $motclef = ''; public static $motentier = true; public static $previewLength = [ 100 => '100 caractères', 200 => '200 caractères', 300 => '300 caractères', 400 => '400 caractères', ]; private function update() { if ( $this->getData(['module', $this->getUrl(0), 'config']) === NULL || $this->getData(['module', $this->getUrl(0), 'theme']) === NULL || !file_exists(self::DATADIRECTORY . $this->getUrl(0) . '/theme.css') ) { $this->init(); } $versionData = $this->getData(['module', $this->getUrl(0), 'config', 'versionData']); if (version_compare($versionData, '2.2', '<')) { if (is_dir(self::DATADIRECTORY . 'pages/')) { $this->copyDir(self::DATADIRECTORY . 'pages/' . $this->getUrl(0), self::DATADIRECTORY . $this->getUrl(0)); $this->deleteDir(self::DATADIRECTORY . 'pages/'); } $this->setData(['module', $this->getUrl(0), 'config', 'versionData', '2.2']); } } private function init() { $fileCSS = self::DATADIRECTORY . $this->getUrl(0) . '/theme.css'; if ($this->getData(['module', $this->getUrl(0)]) === null) { require_once('module/search/ressource/defaultdata.php'); $this->setData(['module', $this->getUrl(0), 'config', init::$defaultConfig]); $this->setData(['module', $this->getUrl(0), 'theme', init::$defaultTheme]); $this->setData(['module', $this->getUrl(0), 'theme', 'style', self::DATADIRECTORY . $this->getUrl(0) . '/theme.css']); header("Refresh:0"); } if (!is_dir(self::DATADIRECTORY . $this->getUrl(0))) { mkdir(self::DATADIRECTORY . $this->getUrl(0), 0755, true); } if (!file_exists(self::DATADIRECTORY . $this->getUrl(0) . '/theme.css')) { $style = '.keywordColor {background: ' . $this->getData(['module', $this->getUrl(0), 'theme', 'keywordColor']) . ';}'; file_put_contents(self::DATADIRECTORY . $this->getUrl(0) . '/theme.css', $style); $this->setData(['module', $this->getUrl(0), 'theme', 'style', $fileCSS]); } } public function config() { $this->update(); if ( $this->getUser('permission', __CLASS__, __FUNCTION__) === true && $this->isPost() ) { $style = '.keywordColor {background:' . $this->getInput('searchKeywordColor') . ';}'; $success = is_int(file_put_contents(self::DATADIRECTORY . $this->getUrl(0) . '/theme.css', $style)); $this->setData([ 'module', $this->getUrl(0), 'config', [ 'submitText' => $this->getInput('searchSubmitText'), 'placeHolder' => $this->getInput('searchPlaceHolder'), 'resultHideContent' => $this->getInput('searchResultHideContent', helper::FILTER_BOOLEAN), 'previewLength' => $this->getInput('searchPreviewLength', helper::FILTER_INT), 'versionData' => $this->getData(['module', $this->getUrl(0), 'config', 'versionData']) ] ]); $this->setData([ 'module', $this->getUrl(0), 'theme', [ 'keywordColor' => $this->getInput('searchKeywordColor'), 'style' => $success ? self::DATADIRECTORY . $this->getUrl(0) . '/theme.css' : '', ] ]); $this->addOutput([ 'redirect' => helper::baseUrl() . $this->getUrl(), 'notification' => $success ? 'Modifications enregistrées' : 'Modifications non enregistrées !', 'state' => $success ]); } $this->addOutput([ 'title' => helper::translate('Configuration du module'), 'view' => 'config', 'vendor' => [ 'tinycolorpicker' ] ]); } public function index() { $this->init(); if ( $this->isPost() ) { $result = []; $r = []; self::$motclef = $this->getInput('searchMotphraseclef'); $motclef = self::$motclef; $arraymotclef = explode(' ', $motclef); $motclef = ''; foreach ($arraymotclef as $key => $value) { if (mb_strlen($value, 'UTF-8') > 2 && $value !== 'les' && $value !== 'des' && $value !== 'une' && $value !== 'aux') $motclef .= $value . ' '; } if ($motclef !== '') $motclef = mb_substr($motclef, 0, mb_strlen($motclef, 'UTF-8') - 1, 'UTF-8'); self::$motentier = $this->getInput('searchMotentier', helper::FILTER_BOOLEAN); if ($motclef !== '') { foreach ($this->getHierarchy(null, false, null) as $parentId => $childIds) { $contentPath = self::DATA_DIR . self::$siteContent . '/content/' . $this->getData(['page', $parentId, 'content']); $timestamp = file_exists($contentPath) ? filemtime($contentPath) : 0; if ( $this->getData(['page', $parentId, 'disable']) === false && $this->getUser('role') >= $this->getData(['page', $parentId, 'role']) && $this->getData(['page', $parentId, 'block']) !== 'bar' ) { $url = $parentId; $titre = $this->getData(['page', $parentId, 'title']); $content = $this->getPage($parentId, self::$siteContent); $content = $titre . ' ' . $content; $tempData = $this->occurrence($url, $titre, $content, $motclef, self::$motentier, $timestamp); if (is_array($tempData)) { $result[] = $tempData; } } foreach ($childIds as $childId) { $contentChildPath = self::DATA_DIR . self::$siteContent . '/content/' . $this->getData(['page', $childId, 'content']); $timestampChild = file_exists($contentChildPath) ? filemtime($contentChildPath) : 0; if ( $this->getData(['page', $childId, 'disable']) === false && $this->getUser('role') >= $this->getData(['page', $childId, 'role']) && $this->getData(['page', $childId, 'block']) !== 'bar' ) { $url = $childId; $titre = $this->getData(['page', $childId, 'title']); $content = $this->getPage($childId, self::$siteContent); $content = $titre . ' ' . $content; $tempData = $this->occurrence($url, $titre, $content, $motclef, self::$motentier, $timestampChild); if (is_array($tempData)) { $result[] = $tempData; } } if ($this->getData(['module', $childId, 'posts'])) { foreach ($this->getData(['module', $childId, 'posts']) as $articleId => $article) { if ($this->getData(['module', $childId, 'posts', $articleId, 'state']) === true) { $url = $childId . '/' . $articleId; $titre = $article['title']; $contenu = ' ' . $titre . ' ' . $article['content']; $articleTimestamp = isset($article['publishedOn']) ? (int)$article['publishedOn'] : 0; $tempData = $this->occurrence($url, $titre, $contenu, $motclef, self::$motentier, $articleTimestamp); if (is_array($tempData)) { $result[] = $tempData; } } } } } if ( $this->getData(['module', $parentId, 'posts']) && $this->getData(['page', $parentId, 'disable']) === false && $this->getUser('role') >= $this->getData(['page', $parentId, 'role']) ) { foreach ($this->getData(['module', $parentId, 'posts']) as $articleId => $article) { if ($this->getData(['module', $parentId, 'posts', $articleId, 'state']) === true) { $url = $parentId . '/' . $articleId; $titre = $article['title']; $contenu = ' ' . $titre . ' ' . $article['content']; $articleTimestamp = isset($article['publishedOn']) ? (int)$article['publishedOn'] : 0; $tempData = $this->occurrence($url, $titre, $contenu, $motclef, self::$motentier, $articleTimestamp); if (is_array($tempData)) { $result[] = $tempData; } } } } } if (count($result) === 0) { self::$resultTitle = helper::translate('Aucun résultat'); self::$resultError = helper::translate('Avez-vous pensé aux accents ?'); } else { self::$resultError = ''; usort($result, function ($a, $b) { if ($a['timestamp'] === $b['timestamp']) { return $b['matches'] <=> $a['matches']; } return $b['timestamp'] <=> $a['timestamp']; }); foreach ($result as $key => $value) { $r[] = $value['preview']; } self::$resultList = implode("", $r); } } $this->addOutput([ 'view' => 'index', 'showBarEditButton' => true, 'showPageContent' => !$this->getData(['module', $this->getUrl(0), 'config', 'resultHideContent']), 'style' => file_exists($this->getData(['module', $this->getUrl(0), 'theme', 'style'])) ? $this->getData(['module', $this->getUrl(0), 'theme', 'style']) : '' ]); } else { $this->addOutput([ 'view' => 'index', 'showBarEditButton' => true, 'showPageContent' => true ]); } } private function occurrence($url, $titre, $contenu, $motclef, $motentier, $timestamp = 0) { $contenu = preg_replace('/<[^>]*>/', ' ', $contenu); $contenu = html_entity_decode($contenu); $a = str_getcsv(html_entity_decode($motclef), ' ', '"', ''); $keywords = '/('; foreach ($a as $key => $value) { $pattern = preg_quote((string) $value, '/'); $keywords .= $motentier === true ? $pattern . '|' : '\b' . $pattern . '\b|'; } $keywords = substr($keywords, 0, strlen($keywords) - 1); $keywords .= ')/i'; $valid = preg_match_all($keywords, $contenu, $matches, PREG_OFFSET_CAPTURE); if ($valid === false) { return null; } if ($valid > 0) { if (($matches[0][0][1]) >= 0) { $resultat = sprintf('<h2><a  href="%s" target="_blank" rel="noopener">%s (%s)</a></h2>', $this->buildEncodedUrl($url), $titre, count($matches[0])); $d = $matches[0][0][1] - 50 < 0 ? 1 : $matches[0][0][1] - 50; $space = $d >= 1 ? strpos($contenu, ' ', $d) : false; $d = $space !== false ? $space : max(0, $d); $previewLength = (int) $this->getData(['module', $this->getUrl(0), 'config', 'previewLength']); $t = mb_substr($contenu, (int) $d, $previewLength > 0 ? $previewLength : 200, 'UTF-8'); $t = preg_replace($keywords, '<span class= "keywordColor">\1</span>', $t); $resultat .= '<p class="searchResult">' . $t . '...</p>'; return ([ 'matches' => count($matches[0]), 'preview' => $resultat, 'timestamp' => $timestamp ]); } } } private function buildEncodedUrl($url) { $parts = explode('/', $url); $encodedParts = array_map('rawurlencode', $parts); return helper::baseUrl(helper::checkRewrite() === false) . implode('/', $encodedParts); } }
